/**
 * Mahjong practice (PLAN.md 2.6): rated "what would you discard" problems from hands played by
 * the CPU (generated by scripts/generate-mahjong-discards.ts, each answer proved by the coach's
 * efficiency calculator), and five drills generated on the spot, on the lesson runner:
 *
 * - **what would you discard**: a hand a few tiles from complete; the best throw is proved the
 *   same way as the problems (fewest tiles from ready, then the most useful tiles you have not
 *   seen, by a clear margin);
 * - **waits**: a ready hand with a stray tile; how many tiles would win, and how many are left;
 * - **name the pattern**: a winning hand built toward a pattern; pick the one it scores;
 * - **score the hand**: count the faan and what you collect, checked by the Hong Kong scorer;
 * - **safe tile**: one player has called three sets; throw the tile the safe-tile ranking
 *   (the coach's) puts clearly safest.
 */
import type { Seat } from '../../../core/contract';
import type { Lesson, LessonStep } from '../../../teach/lesson';
import type { Problem } from '../../../teach/problem';
import type { DrillDef, PracticePack } from '../../practice';
import type { MahjongState, MeldSpec } from '../rules';
import { viewOf } from '../rules';
import type { Kind } from '../core/tiles';
import { codeOf, FLOWER_1, isHonour, isSuited, kindOf, PLAYING_KINDS, SUIT_KINDS, suitOf } from '../core/tiles';
import { evaluateDiscards, picture, readThreats, safetyRanking } from '../strategy';
import type { LessonSpec } from '../learn/game';
import { BASIC, HK, lessonPosition, lessonState, mahjongComputed, mahjongLessonGame, winOnOffer } from '../learn/game';
import { efficiencyProblems, safetyProblems } from '../learn/verify';
import { kindName, patternName } from '../ui/names';
import type { Complete, Knobs, Random } from './build';
import { buildComplete, calledMeld, codes, completeKinds, pick, randomTiles, shuffle } from './build';

function lesson(id: string, title: string, start: string, steps: LessonStep[]): Lesson {
  return { id: `mahjong.drill.${id}`, gameId: 'mahjong', stage: 'table', title, minutes: 1, start, steps };
}

const seedOf = (random: Random, prefix = 'drill') => `${prefix}/${Math.floor(random() * 1e9)}`;

const countsOf = (kinds: readonly Kind[]): number[] => {
  const c = new Array<number>(PLAYING_KINDS).fill(0);
  for (const k of kinds) c[k] = (c[k] ?? 0) + 1;
  return c;
};

/** A lesson state, or null when the tiles asked for do not fit (the drills then try again). */
function tryState(spec: LessonSpec): MahjongState | null {
  try {
    return lessonState(spec);
  } catch {
    return null;
  }
}

// What would you discard

/** The best discards of a position by the coach's calculator, or null unless clearly best. */
export function provedDiscards(state: MahjongState): Kind[] | null {
  const evals = evaluateDiscards(picture(viewOf(state, 0)));
  const fastest = Math.min(...evals.map((e) => e.shanten));
  const most = Math.max(...evals.filter((e) => e.shanten === fastest).map((e) => e.accept));
  const best = evals.filter((e) => e.shanten === fastest && e.accept === most).map((e) => e.kind);
  if (efficiencyProblems(state, best.map(codeOf)).length > 0) return null;
  return best;
}

/** Feedback for the tempting wrong throws: each says what it gives up. */
function discardWrongs(state: MahjongState, best: readonly Kind[]): Record<string, string> {
  const evals = evaluateDiscards(picture(viewOf(state, 0)));
  const fastest = Math.min(...evals.map((e) => e.shanten));
  const out: Record<string, string> = {};
  for (const e of evals) {
    if (best.includes(e.kind)) continue;
    const code = codeOf(e.kind);
    out[code] =
      e.shanten > fastest
        ? `That leaves your hand further from ready: {shanten:${code}} from ready instead of {shanten}.`
        : `That keeps {accept:${code}} useful tiles; the best throw keeps {accept:best}.`;
  }
  return out;
}

export function discardLesson(state: MahjongState, best: readonly Kind[], id = 'discard'): Lesson {
  const ready = Math.min(...evaluateDiscards(picture(viewOf(state, 0))).map((e) => e.shanten)) === 0;
  const success =
    best.length > 1
      ? `Right: the {best:names} each keep the most, {accept:best} useful tiles${ready ? ', and you are ready' : ', {shanten} from ready'}.`
      : `Right: the {best:names} keeps the most, {accept:best} useful tiles${ready ? ', and you are ready' : ', {shanten} from ready'}.`;
  return lesson(id, 'What would you discard?', mahjongLessonGame.notation(state), [
    {
      kind: 'askMove',
      text: 'Your turn. Throw the tile that keeps your hand closest to ready, with the most useful tiles you have not seen.',
      accept: best.map(codeOf),
      wrong: discardWrongs(state, best),
      claim: 'best',
      success,
    },
  ]);
}

function discardDrill(random: Random): Lesson {
  for (;;) {
    const c = buildComplete(random, { suit: null, honour: 0.15, pung: 0.25 });
    if (!c) continue;
    const kinds = shuffle(random, completeKinds(c));
    const damaged = 2 + Math.floor(random() * 3);
    const keep = kinds.slice(damaged);
    const fresh = randomTiles(random, damaged, countsOf(keep));
    const hand = [...keep, ...fresh];
    const state = tryState({ hand: codes(hand), drawn: codeOf(fresh[fresh.length - 1] ?? 0), options: BASIC, turns: 3 + Math.floor(random() * 6), seed: seedOf(random) });
    if (!state || mahjongLessonGame.moves(state).includes('win')) continue;
    const best = provedDiscards(state);
    if (best) return discardLesson(state, best);
  }
}

// Waits

function waitsDrill(random: Random): Lesson {
  for (;;) {
    const c = buildComplete(random, { suit: null, honour: 0.2, pung: 0.3 });
    if (!c) continue;
    const kinds = shuffle(random, completeKinds(c)).slice(1);
    const used = countsOf(kinds);
    // A stray tile: an honour or a far terminal nothing in the hand connects with.
    const strays: Kind[] = [];
    for (let k = 0; k < PLAYING_KINDS; k++) {
      if ((used[k] ?? 0) > 0) continue;
      if (isHonour(k) || (isSuited(k) && [-2, -1, 1, 2].every((d) => { const n = k + d; return n < 0 || n >= SUIT_KINDS || suitOf(n) !== suitOf(k) || (used[n] ?? 0) === 0; }))) strays.push(k);
    }
    if (strays.length === 0) continue;
    const stray = pick(random, strays);
    const state = tryState({ hand: codes([...kinds, stray]), drawn: codeOf(stray), options: BASIC, turns: 4 + Math.floor(random() * 6), seed: seedOf(random) });
    if (!state) continue;
    const x = codeOf(stray);
    const values = mahjongComputed(state);
    if (typeof values[`waits:${x}`] !== 'number' || mahjongLessonGame.moves(state).includes('win')) continue;
    return lesson('waits', 'Waits', mahjongLessonGame.notation(state), [
      { kind: 'askNumber', text: `Throw the ${kindName(stray)} and your hand is ready. How many different tiles would then complete it?`, answer: `waits:${x}`, success: `Yes, {waits:${x}}: the {waits:names:${x}}.` },
      { kind: 'askMove', text: `Throw the ${kindName(stray)}.`, accept: [x], claim: 'legal', success: 'Ready.' },
      { kind: 'askNumber', text: 'Of those winning tiles, how many copies have you not seen?', answer: 'waits:left', success: 'Yes, {waits:left}: the ones not in your hand or on the table.' },
    ]);
  }
}

// Winning hands: name the pattern, score the hand

/** Patterns the drills build toward, with the knobs that make them likely. */
const TARGETS: Readonly<Record<string, (random: Random) => Knobs>> = {
  'all-chows': () => ({ suit: null, honour: 0, pung: 0 }),
  'all-pungs': () => ({ suit: null, honour: 0.3, pung: 1 }),
  'mixed-one-suit': (random) => ({ suit: Math.floor(random() * 3), honour: 0.35, pung: 0.4 }),
  'pure-one-suit': (random) => ({ suit: Math.floor(random() * 3), honour: 0, pung: 0.3 }),
  'dragon-pung': () => ({ suit: null, honour: 0.4, pung: 0.3 }),
  'seat-wind': () => ({ suit: null, honour: 0.45, pung: 0.3 }),
  'prevailing-wind': () => ({ suit: null, honour: 0.45, pung: 0.3 }),
};

export interface WinningHand {
  readonly state: MahjongState;
  readonly lines: readonly string[];
  readonly selfDrawn: boolean;
}

/** A hand you can win now, worth the minimum but not a limit hand, scoring `target` when given. */
export function winningHand(random: Random, target: string | null): WinningHand {
  for (;;) {
    const goal = target ?? pick(random, Object.keys(TARGETS));
    const knobs = (TARGETS[goal] ?? TARGETS['all-chows'])?.(random) as Knobs;
    const c: Complete | null = buildComplete(random, knobs);
    if (!c) continue;
    const called = c.sets.filter((_, i) => i < 2 && random() < 0.35);
    const melds: MeldSpec[] = called.map((s) => calledMeld(random, s));
    const concealed = completeKinds({ sets: c.sets.filter((s) => !called.includes(s)), pair: c.pair });
    const win = pick(random, concealed);
    const selfDrawn = random() < 0.5;
    const hand = [...concealed];
    if (!selfDrawn) hand.splice(hand.indexOf(win), 1);
    const bonus = shuffle(random, Array.from({ length: 8 }, (_, i) => FLOWER_1 + i)).slice(0, Math.floor(random() * 3));
    const state = tryState({
      hand: codes(hand),
      ...(selfDrawn ? { drawn: codeOf(win) } : { offer: { seat: (1 + Math.floor(random() * 3)), tile: codeOf(win) } }),
      melds: [melds],
      options: HK,
      dealer: Math.floor(random() * 4),
      round: Math.floor(random() * 2),
      bonus: [codes(bonus)],
      avoid: codeOf(win),
      turns: 3 + Math.floor(random() * 5),
      seed: seedOf(random),
    });
    if (!state) continue;
    const offer = winOnOffer(state);
    if (!offer || offer.score.limit || offer.score.total < Number(state.config.options.minFaan)) continue;
    const lines = offer.score.lines.map((l) => l.id);
    if (target && !lines.includes(target)) continue;
    if (!mahjongLessonGame.moves(state).includes('win')) continue;
    return { state, lines, selfDrawn };
  }
}

/** "The player on your right", and so on. */
export function playerPhrase(seat: Seat): string {
  return ['You', 'The player on your right', 'The player across', 'The player on your left'][seat % 4] ?? 'A player';
}

/** How the hand is being won, and where you sit, in words. */
function situation(h: WinningHand): string {
  const s = h.state;
  const how = h.selfDrawn && s.drawn ? `You drew the ${kindName(kindOf(s.drawn))}, and your hand is complete.` : `${playerPhrase(s.claim?.from ?? 1)} threw the {claim:tile}, and it completes your hand.`;
  return `${how} You sit {wind:seat} in the {wind:round} round.`;
}

/** Patterns a hand might be thought to score, for the wrong answers. */
const NAMEABLE = ['all-chows', 'all-pungs', 'mixed-one-suit', 'pure-one-suit', 'dragon-pung', 'seat-wind', 'prevailing-wind', 'concealed', 'self-drawn'] as const;

function patternsDrill(random: Random): Lesson {
  const target = pick(random, Object.keys(TARGETS));
  const h = winningHand(random, target);
  const wrong = shuffle(
    random,
    NAMEABLE.filter((id) => !h.lines.includes(id)),
  ).slice(0, 2);
  const options = shuffle(random, [
    { text: patternName(target), correct: true, why: `Right: ${patternName(target).toLowerCase()} is worth {win:line:${target}} here, {win:faan} faan for the whole hand.` },
    ...wrong.map((id) => ({ text: patternName(id), why: `This hand does not score ${patternName(id).toLowerCase()}. It does score ${patternName(target).toLowerCase()}.` })),
  ]);
  return lesson('patterns', 'Name the pattern', mahjongLessonGame.notation(h.state), [
    { kind: 'askChoice', text: `${situation(h)} Which of these patterns does it score?`, options },
    { kind: 'askMove', text: 'Win, and read every line on the sheet.', accept: ['win'], claim: 'legal', success: '{win:faan} faan in all.' },
  ]);
}

function scoreDrill(random: Random): Lesson {
  const h = winningHand(random, null);
  const pays = h.selfDrawn ? 'Self-drawn: each of the others pays twice the base.' : 'On a throw: the thrower pays twice the base, the other two once each.';
  return lesson('score', 'Score the hand', mahjongLessonGame.notation(h.state), [
    { kind: 'askNumber', text: `${situation(h)} How many faan is it worth?`, answer: 'win:faan', success: 'Yes, {win:faan} faan.' },
    { kind: 'askNumber', text: `The base for {win:faan} faan is {win:base}. ${pays} How much do you collect in all?`, answer: 'win:total', success: 'Yes, {win:total}.' },
    { kind: 'askMove', text: 'Win, and check your count against the sheet.', accept: ['win'], claim: 'legal', success: 'The sheet agrees: {win:faan} faan, {win:total} in all.' },
  ]);
}

// Safe tile

function safeDrill(random: Random): Lesson {
  for (;;) {
    const threat = (1 + Math.floor(random() * 3));
    const suit = Math.floor(random() * 3);
    const used = new Array<number>(PLAYING_KINDS).fill(0);
    const take = (kinds: readonly Kind[]) => {
      for (const k of kinds) used[k] = (used[k] ?? 0) + 1;
    };
    // Three called sets, two of them in one suit.
    const sets = [0, 1, 2].map((i) => {
      if (i === 2 && random() < 0.5) return { type: 'pung' as const, kind: 31 + Math.floor(random() * 3) };
      return random() < 0.5 ? { type: 'pung' as const, kind: suit * 9 + Math.floor(random() * 9) } : { type: 'chow' as const, kind: suit * 9 + Math.floor(random() * 7) };
    });
    const setTiles = sets.flatMap((s) => (s.type === 'pung' ? [s.kind, s.kind, s.kind] : [s.kind, s.kind + 1, s.kind + 2]));
    if (countsOf(setTiles).some((n) => n > 4)) continue;
    take(setTiles);
    const melds: MeldSpec[][] = [[], [], [], []];
    melds[threat] = sets.map((s) => {
      const tiles = (s.type === 'pung' ? [s.kind, s.kind, s.kind] : [s.kind, s.kind + 1, s.kind + 2]).map(codeOf).join(' ');
      if (s.type === 'chow') return { type: 'chow', tiles, from: ((threat + 3) % 4) };
      const others = [0, 1, 2, 3].filter((x) => x !== threat);
      return { type: 'pung', tiles, from: pick(random, others) };
    });
    const discards = [0, 1, 2, 3].map((seat) => {
      const n = seat === threat ? 7 + Math.floor(random() * 4) : 5 + Math.floor(random() * 5);
      return randomTiles(random, n, used, (k) => seat !== threat || !isSuited(k) || suitOf(k) !== suit);
    });
    // Your hand: random tiles, often one the threatening player threw.
    const thrown = discards[threat] ?? [];
    const mine = random() < 0.7 && thrown.length > 0 ? [pick(random, thrown)] : [];
    for (const k of mine) if ((used[k] ?? 0) < 4) used[k] = (used[k] ?? 0) + 1;
    const hand = [...mine, ...randomTiles(random, 14 - mine.length, used)];
    const state = tryState({ hand: codes(hand), drawn: codeOf(hand[hand.length - 1] ?? 0), melds, discards: discards.map(codes), options: BASIC, seed: seedOf(random, 'safety') });
    if (!state || mahjongLessonGame.moves(state).includes('win')) continue;
    const p = picture(viewOf(state, 0));
    if ((readThreats(p.view).find((t) => t.seat === threat)?.level ?? 0) < 0.75) continue;
    const ranking = safetyRanking(p);
    const safest = ranking[0]?.kind;
    if (safest === undefined || safetyProblems(state, [codeOf(safest)]).length > 0) continue;
    const worst = ranking[ranking.length - 1]?.kind ?? safest;
    const why = thrown.includes(safest)
      ? `They threw the ${kindName(safest)} themselves.`
      : isHonour(safest) && (p.unseen[safest] ?? 0) === 0
        ? `Every other ${kindName(safest)} is already in sight.`
        : `It is well away from the suit they are collecting.`;
    return lesson('safe', 'Safe tile', mahjongLessonGame.notation(state), [
      {
        kind: 'askMove',
        text: `${playerPhrase(threat)} has called three sets and may well be ready. Throw your safest tile.`,
        accept: [codeOf(safest)],
        wrong: worst !== safest ? { [codeOf(worst)]: `That is your most dangerous tile against them. ${why}` } : {},
        claim: 'best',
        success: `Right: the ${kindName(safest)}. ${why}`,
      },
    ]);
  }
}

export const MAHJONG_DRILLS: readonly DrillDef[] = [
  { id: 'drill-mahjong-discard', make: discardDrill },
  { id: 'drill-mahjong-waits', make: waitsDrill },
  { id: 'drill-mahjong-patterns', make: patternsDrill },
  { id: 'drill-mahjong-score', make: scoreDrill },
  { id: 'drill-mahjong-safe', make: safeDrill },
];

interface DiscardFile {
  /** Each problem: the position as a lesson spec (every hand named), the best throws, a rating and themes. */
  readonly problems: readonly { id: string; spec: LessonSpec; best: string[]; rating: number; themes: string[] }[];
}

export async function loadMahjongPractice(): Promise<PracticePack> {
  const file = (await import('./discards.json')).default as unknown as DiscardFile;
  const problems: Problem[] = file.problems.map((p) => ({ id: p.id, position: lessonPosition(p.spec), setup: null, line: p.best.slice(0, 1), alsoFirst: p.best.slice(1), rating: p.rating, themes: p.themes }));
  return {
    problems,
    sets: [{ id: 'discards', themes: ['mj-discard'], chips: ['mj-lone', 'mj-shape', 'mj-count', 'mj-ready'] }],
    drills: MAHJONG_DRILLS,
    attribution: null,
    game: mahjongLessonGame,
    themeOrder: ['mj-ready', 'mj-count', 'mj-shape', 'mj-lone', 'mj-discard'],
  };
}

